"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Plus, Trash2, ClipboardList } from "lucide-react";
import TaskFormModal from "./TaskFormModal"; // Importun doğruluğundan emin ol
import { deleteTask } from "@/app/actions/task-actions";

export default function TaskListClient({ initialTasks }: { initialTasks: any[] }) {
  // Modalın açık/kapalı olma durumunu kontrol eden state
  const [isModalOpen, setIsModalOpen] = useState(false);

  return (
    <div className="flex flex-col gap-6 w-full p-6">
      {/* Üst Kısım: Başlık ve "Nieuwe Taak" Butonu */}
      <div className="flex justify-between items-center bg-white p-6 rounded-xl shadow-sm border border-gray-100">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2 text-gray-800">
            <ClipboardList className="text-blue-600 w-6 h-6" /> 
            Takenlijst
          </h1>
          <p className="text-sm text-gray-500 mt-1">Beheer je scrum documentatie ve tasks.</p>
        </div>
        
        {/* İŞTE O BUTON: Tıklandığında setIsModalOpen(true) yaparak modalı açar */}
        <Button 
          onClick={() => setIsModalOpen(true)}
          className="bg-blue-600 hover:bg-blue-700 text-white font-semibold px-4 py-2 rounded-lg flex items-center gap-2 transition-all shadow-md active:scale-95"
        >
          <Plus className="w-5 h-5" />
          <span>Nieuwe Taak</span>
        </Button>
      </div>

      {/* Liste Kısmı */}
      <div className="grid gap-4">
        {initialTasks && initialTasks.length > 0 ? (
          initialTasks.map((task) => (
            <div 
              key={task.id} 
              className="group p-5 bg-white border border-gray-200 rounded-xl shadow-sm hover:shadow-md transition-all flex justify-between items-center"
            >
              <div className="flex-1">
                <h3 className="font-bold text-lg text-gray-800 group-hover:text-blue-600 transition-colors">
                  {task.title}
                </h3>
                {task.description && (
                  <p className="text-gray-500 text-sm mt-1">{task.description}</p>
                )}
              </div>
              
              <Button 
                variant="ghost" 
                size="icon" 
                className="text-red-400 hover:text-red-600 hover:bg-red-50 rounded-full transition-colors"
                onClick={async () => {
                   if(confirm("Bu görevi silmek istediğine emin misin?")) {
                     await deleteTask(task.id);
                   }
                }}
              >
                <Trash2 className="w-5 h-5" />
              </Button>
            </div>
          ))
        ) : (
          <div className="text-center py-20 bg-gray-50 border-2 border-dashed border-gray-200 rounded-2xl">
            <p className="text-gray-400 italic font-medium">Henüz bir görev eklenmemiş.</p>
            <Button 
              variant="link" 
              onClick={() => setIsModalOpen(true)}
              className="text-blue-500 mt-2"
            >
              Hemen bir tane oluştur
            </Button>
          </div>
        )}
      </div>

      {/* MODAL BİLEŞENİ: En altta durmalı */}
      <TaskFormModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
      />
    </div>
  );
}