"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";

export async function createNewTask(title: string, description: string, content: string) {
  try {
    // Şemana göre bir kullanıcı bul veya oluştur
    let user = await prisma.user.findFirst();
    if (!user) {
      user = await prisma.user.create({
        data: {
          email: "student@rocmondriaan.nl",
          name: "WorkSpace Student",
          password: "password123", // Gerçek projede hashlenmeli
          role: "USER"
        }
      });
    }

    // Senin Task modelindeki alanlara göre kayıt yapıyoruz
    await prisma.task.create({
      data: {
        title,
        description, // Şemandaki description alanı
        content,     // Şemandaki LongText olan content alanı
        userId: user.id,
        status: "TODO",
        priority: "MEDIUM",
        sprint: "1", // Varsayılan değer
      },
    });

    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    console.error("Prisma Create Error:", error);
    return { success: false };
  }
}

export async function deleteTask(id: string) {
  try {
    await prisma.task.delete({
      where: { id },
    });
    revalidatePath("/tasks");
    return { success: true };
  } catch (error) {
    return { success: false };
  }
}